package com.mohymods.kingdomsmp.economy;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.io.IOException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class FarmerQuestStoreTest {
 @TempDir Path dir;final UUID p=UUID.randomUUID();
 EconomyStore open()throws IOException{return EconomyStore.open(dir);}
 void enroll(EconomyStore s)throws IOException{s.changeProfession(UUID.randomUUID(),p,"enroll","","farmer");}
 String id(ProfessionRank rank,int n){return FarmerQuests.id(rank,n);}
 void proof(EconomyStore s,ProfessionRank rank,int n)throws Exception{String quest=id(rank,n);if(FarmerQuests.food(quest)){var inputs=new HashMap<String,Integer>();FarmerDeliveries.family(quest).forEach(item->inputs.put(item,1));var pending=s.prepareFarmerDelivery(UUID.randomUUID(),p,quest,"fixture native proof",inputs);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));}else if(FarmerQuests.inspection(quest))s.approveFarmerInspection(UUID.randomUUID(),UUID.randomUUID(),p,quest,"fixture administrator site proof");else s.completeFarmerQuest(UUID.randomUUID(),p,quest,"fixture server event proof");}
 @Test void canonicalProofAwardsOnceAndPersistsWithoutChangingMoneyOrNativeReceipt()throws Exception{var s=open();enroll(s);long receipt=s.expectedReceipt(p);UUID op=UUID.randomUUID();s.completeFarmerQuest(op,p,id(ProfessionRank.APPRENTICE,1),"32 distinct cells tilled");s.completeFarmerQuest(op,p,id(ProfessionRank.APPRENTICE,1),"32 distinct cells tilled");assertEquals(100,open().professions(p).track(Profession.FARMER).xp());assertEquals(0,s.balance(p));assertEquals(receipt,s.expectedReceipt(p));assertThrows(IllegalStateException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,1),"repeat"));}
 @Test void actualApprovedBandProofsAloneChangeRankAndInactiveProgressSurvives()throws Exception{var s=open();enroll(s);assertThrows(IllegalStateException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.JOURNEYMAN,1),"future-band"));for(int n=1;n<=8;n++)proof(s,ProfessionRank.APPRENTICE,n);assertEquals(ProfessionRank.JOURNEYMAN,s.professions(p).rank(Profession.FARMER,FarmerQuests.catalog()));for(int n=1;n<=8;n++)proof(s,ProfessionRank.JOURNEYMAN,n);assertEquals(ProfessionRank.JOURNEYMAN,s.professions(p).rank(Profession.FARMER,FarmerQuests.catalog()));for(int n=1;n<=8;n++)proof(s,ProfessionRank.MASTER,n);assertEquals(ProfessionRank.MASTER,open().professions(p).rank(Profession.FARMER,FarmerQuests.catalog()));assertEquals(4800,s.professions(p).track(Profession.FARMER).xp());}
 @Test void inactiveForeignOrMissingEvidenceCannotAdvance()throws Exception{var s=open();enroll(s);s.adminSet(UUID.randomUUID(),p,p,15000,"switch funding");s.changeProfession(UUID.randomUUID(),p,"switch","farmer","builder");assertThrows(IllegalStateException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,1),"real proof"));assertThrows(IllegalArgumentException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,"kingdom_smp:builder/a01","foreign"));assertThrows(IllegalArgumentException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,1),""));}
 @Test void postRenameFailureRecoversExactlyOneAward()throws Exception{var s=open();enroll(s);var failing=EconomyStore.open(dir,(path,nbt)->{AtomicNbt.write(path,nbt);throw new IOException("after rename");});assertThrows(IOException.class,()->failing.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,1),"32 real cells"));assertEquals(100,open().professions(p).track(Profession.FARMER).xp());}
 @Test void nativeFoodPrepareCancelCommitReplayAndReloadAreOneQuestBoundary()throws Exception{var s=open();enroll(s);var op=UUID.randomUUID();var pending=s.prepareFarmerDelivery(op,p,id(ProfessionRank.APPRENTICE,7),"32 actual bread",Map.of("minecraft:bread",32));assertEquals(0,s.professions(p).track(Profession.FARMER).xp());assertFalse(s.recoverItem(EconomyStore.Receipt.empty()));assertEquals(0,open().professions(p).track(Profession.FARMER).xp());pending=s.prepareFarmerDelivery(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,7),"32 actual bread",Map.of("minecraft:bread",32));assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertEquals(100,open().professions(p).track(Profession.FARMER).xp());assertEquals(pending.sequence(),s.expectedReceipt(p));assertThrows(IllegalStateException.class,()->s.prepareFarmerDelivery(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,7),"repeat",Map.of("minecraft:bread",32)));}
 @Test void malformedNativeFoodNeverPreparesOrAwards()throws Exception{var s=open();enroll(s);long rev=s.revision();assertThrows(IllegalArgumentException.class,()->s.prepareFarmerDelivery(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,7),"forged",Map.of("minecraft:diamond",32)));assertTrue(s.pendingItem().isEmpty());assertEquals(rev,s.revision());assertEquals(0,s.professions(p).track(Profession.FARMER).xp());}
 @Test void inspectionAndFoodCannotUseEventCompletionBypass()throws Exception{var s=open();enroll(s);assertThrows(IllegalArgumentException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,7),"not consumed"));assertThrows(IllegalArgumentException.class,()->s.completeFarmerQuest(UUID.randomUUID(),p,id(ProfessionRank.APPRENTICE,8),"not inspected"));assertThrows(IllegalArgumentException.class,()->s.approveFarmerInspection(UUID.randomUUID(),p,p,id(ProfessionRank.APPRENTICE,1),"not an inspection"));}
 @Test void contractsCreditOnlyTheirActualObjectiveBandAndDistinctCanonicalPeriods()throws Exception{var s=open();enroll(s);var wheat=new net.minecraft.nbt.CompoundTag();wheat.putString("id","minecraft:wheat");wheat.putInt("count",1);var pending=s.prepareContract(UUID.randomUUID(),p,"farmer","daily",10,64,80,2000,wheat);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));for(int n=1;n<=8;n++)proof(s,ProfessionRank.APPRENTICE,n);assertEquals(1,s.farmerContractPeriods(p,ProfessionRank.APPRENTICE,"daily"));assertEquals(0,s.farmerContractPeriods(p,ProfessionRank.JOURNEYMAN,"daily"));pending=s.prepareContract(UUID.randomUUID(),p,"farmer","daily",11,64,80,2000,wheat);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));assertEquals(1,open().farmerContractPeriods(p,ProfessionRank.JOURNEYMAN,"daily"));assertEquals(0,s.farmerContractPeriods(p,ProfessionRank.MASTER,"daily"));}
}
